    #[test]
    fn decimal_literals_within_the_resource_limit_still_parse() {
        for literal in ["1e1000", "1e-1000", "1.25e1000", "1.25e-1000"] {
            parse(literal).unwrap_or_else(|e| panic!("{literal} is within the limit, failed: {e}"));
        }
    }

